arguments.file_text:
@page "/settings"
@using sv_fcb4179dde474da2a8ad83664a104605.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </div>
</div>

<!-- Session revoke confirmation modal -->
@if (_showRevokeConfirm)
{
    <div class="modal-backdrop show" @onclick="() => _showRevokeConfirm = false"></div>
    <div class="modal d-block" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="() => _showRevokeConfirm = false"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_revokeSessionDevice</strong>?</p>
                    <p class="text-muted small">This will sign out that device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="() => _showRevokeConfirm = false">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    // --- Section navigation ---
    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // --- Toast ---
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // --- Profile ---
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    // --- Notifications ---
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private readonly List<string> _allChannels = ["general", "announcements", "engineering", "design", "random"];
    private HashSet<string> _mutedChannels = new();

    // --- Security ---
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirm;
    private string? _revokeSessionId;
    private string? _revokeSessionDevice;

    // --- Appearance ---
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private static readonly string[] Themes = ["Light", "Dark", "System"];
    private static readonly string[] FontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var secTask = SettingsService.GetSecuritySettingsAsync();
        var appTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, secTask, appTask);

        ApplyProfile(await profileTask);
        ApplyNotificationPrefs(await notifTask);
        _securitySettings = await secTask;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
        ApplyAppearance(await appTask);
    }

    private void ApplyProfile(UserProfile p)
    {
        _savedProfile = p;
        _displayName = p.DisplayName;
        _email = p.Email;
        _bio = p.Bio;
        _avatarUrl = p.AvatarUrl;
    }

    private void ApplyNotificationPrefs(NotificationPrefs prefs)
    {
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
    }

    private void ApplyAppearance(AppearanceSettings s)
    {
        _theme = s.Theme;
        _fontSize = s.FontSize;
        _language = s.Language;
        _compactMode = s.CompactMode;
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // ========== Profile ==========
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null) ApplyProfile(_savedProfile);
    }

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h3>Profile</h3>
        <hr />

        <div class="row mb-4">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input class="form-control" @bind="_displayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                </div>
            </div>
            <div class="col-md-4 text-center">
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                </div>
                <div class="mt-2 small text-muted text-break">@_avatarUrl</div>
            </div>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    // ========== Notifications ==========
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h3>Notifications</h3>
        <hr />

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <h5>Channel Preferences</h5>
        <div class="mb-4">
            @foreach (var channel in _allChannels)
            {
                var ch = channel;
                var isMuted = _mutedChannels.Contains(ch);
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
                           checked="@isMuted"
                           @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{ch}")">Mute <strong>#@ch</strong></label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
    };

    // ========== Security ==========
    private async Task UpdatePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("Passwords do not match.", true);
            return;
        }
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _passwordPanelOpen = false;
            await ShowToast("Password updated successfully!");
        }
        catch (InvalidOperationException ex)
        {
            await ShowToast(ex.Message, true);
        }
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _revokeSessionId = session.Id;
        _revokeSessionDevice = session.Device;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeConfirm = false;
        await ShowToast("Session revoked.");
    }

    private string FormatRelativeTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h3>Security</h3>
        <hr />

        <!-- Change Password -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
            </div>
            @if (_passwordPanelOpen)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>

                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <div class="text-muted small mt-2">
                            Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <div class="mt-1">
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <h5>Active Sessions</h5>
        @if (_securitySettings?.Sessions is { Count: > 0 })
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            var isCurrentSession = session == _securitySettings.Sessions[0];
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrentSession)
                                    {
                                        <span class="badge bg-info ms-2">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatRelativeTime(session.LastActive)</td>
                                <td>
                                    @if (!isCurrentSession)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => RequestRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
    };

    // ========== Appearance ==========
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };

    private string PreviewBackground => _theme switch
    {
        "Dark" => "#1e1e1e",
        _ => "#ffffff"
    };

    private string PreviewColor => _theme switch
    {
        "Dark" => "#d4d4d4",
        _ => "#212529"
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h3>Appearance</h3>
        <hr />

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <label class="form-label fw-bold">Theme</label>
                    <div>
                        @foreach (var t in Themes)
                        {
                            var theme = t;
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
