+        </div>
+    };
+
+    // ========== Notifications ==========
+    private void ToggleMutedChannel(string channel, bool muted)
+    {
+        if (muted) _mutedChannels.Add(channel);
+        else _mutedChannels.Remove(channel);
+    }
+
+    private async Task SaveNotificationPrefs()
+    {
+        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        await ShowToast("Notification preferences saved!");
+    }
+
+    private RenderFragment RenderNotificationsSection() => __builder =>
+    {
+        <h3>Notifications</h3>
+        <hr />
+
+        <div class="mb-4">
+            <div class="form-check form-switch mb-3">
+                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
+                <label class="form-check-label" for="emailNotif">Email Notifications</label>
+            </div>
+            <div class="form-check form-switch mb-3">
+                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
+                <label class="form-check-label" for="pushNotif">Push Notifications</label>
+            </div>
+            <div class="form-check form-switch mb-3">
+                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
+                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
+            </div>
+        </div>
+
+        <h5>Channel Preferences</h5>
+        <div class="mb-4">
+            @foreach (var channel in _allChannels)
+            {
+                var ch = channel;
+                var isMuted = _mutedChannels.Contains(ch);
+                <div class="form-check mb-2">
+                    <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
+                           checked="@isMuted"
+                           @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
+                    <label class="form-check-label" for="@($"ch-{ch}")">Mute <strong>#@ch</strong></label>
+                </div>
+            }
+        </div>
+
+        <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
+    };
+
+    // ========== Security ==========
+    private async Task UpdatePassword()
+    {
+        if (_newPassword != _confirmPassword)
+        {
+            await ShowToast("Passwords do not match.", true);
+            return;
+        }
+        try
+        {
+            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+            _currentPassword = "";
+            _newPassword = "";
+            _confirmPassword = "";
+            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+            _passwordPanelOpen = false;
+            await ShowToast("Password updated successfully!");
+        }
+        catch (InvalidOperationException ex)
+        {
+            await ShowToast(ex.Message, true);
+        }
+    }
+
+    private void RequestRevokeSession(ActiveSession session)
+    {
+        _revokeSessionId = session.Id;
+        _revokeSessionDevice = session.Device;
+        _showRevokeConfirm = true;
+    }
+
+    private async Task ConfirmRevokeSession()
+    {
+        if (_revokeSessionId is not null)
+        {
+            await SettingsService.RevokeSessionAsync(_revokeSessionId);
+            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        }
+        _showRevokeConfirm = false;
+        await ShowToast("Session revoked.");
+    }
+
+    private string FormatRelativeTime(DateTime dt)
+    {
+        var diff = DateTime.UtcNow - dt;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        return $"{(int)diff.TotalDays}d ago";
+    }
+
+    private RenderFragment RenderSecuritySection() => __builder =>
+    {
+        <h3>Security</h3>
+        <hr />
+
+        <!-- Change Password -->
+        <div class="card mb-4">
+            <div class="card-header d-flex justify-content-between align-items-center"
+                 style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
+                <span>Change Password</span>
+                <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
+            </div>
+            @if (_passwordPanelOpen)
+            {
+                <div class="card-body">
+                    <div class="mb-3">
+                        <label class="form-label">Current Password</label>
+                        <input type="password" class="form-control" @bind="_currentPassword" />
+                    </div>
+                    <div class="mb-3">
+                        <label class="form-label">New Password</label>
+                        <input type="password" class="form-control" @bind="_newPassword" />
+                    </div>
+                    <div class="mb-3">
+                        <label class="form-label">Confirm Password</label>
+                        <input type="password" class="form-control" @bind="_confirmPassword" />
+                    </div>
+                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
+
+                    @if (_securitySettings?.LastPasswordChange is not null)
+                    {
+                        <div class="text-muted small mt-2">
+                            Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
+                        </div>
+                    }
+                </div>
+            }
+        </div>
+
+        <!-- Two-Factor Authentication -->
+        <div class="card mb-4">
+            <div class="card-body d-flex justify-content-between align-items-center">
+                <div>
+                    <strong>Two-Factor Authentication</strong>
+                    <div class="mt-1">
+                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
+                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
+                        </span>
+                    </div>
+                </div>
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
+                </div>
+            </div>
+        </div>
+
+        <!-- Active Sessions -->
+        <h5>Active Sessions</h5>
+        @if (_securitySettings?.Sessions is { Count: > 0 })
+        {
+            <div class="table-responsive">
+                <table class="table table-hover">
+                    <thead>
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th></th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @foreach (var session in _securitySettings.Sessions)
+                        {
+                            var isCurrentSession = session == _securitySettings.Sessions[0];
+                            <tr>
+                                <td>
+                                    @session.Device
+                                    @if (isCurrentSession)
+                                    {
+                                        <span class="badge bg-info ms-2">Current</span>
+                                    }
+                                </td>
+                                <td>@session.Location</td>
+                                <td>@FormatRelativeTime(session.LastActive)</td>
+                                <td>
+                                    @if (!isCurrentSession)
+                                    {
+                                        <button class="btn btn-sm btn-outline-danger"
+                                                @onclick="() => RequestRevokeSession(session)">
+                                            Revoke
+                                        </button>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    </tbody>
+                </table>
+            </div>
+        }
+    };
+
+    // ========== Appearance ==========
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        await ShowToast("Appearance settings saved!");
+    }
+
+    private string PreviewFontSize => _fontSize switch
+    {
+        "Small" => "0.85rem",
+        "Large" => "1.2rem",
+        _ => "1rem"
+    };
+
+    private string PreviewBackground => _theme switch
+    {
+        "Dark" => "#1e1e1e",
+        _ => "#ffffff"
+    };
+
+    private string PreviewColor => _theme switch
+    {
+        "Dark" => "#d4d4d4",
+        _ => "#212529"
+    };
+
+    private RenderFragment RenderAppearanceSection() => __builder =>
+    {
+        <h3>Appearance</h3>
+        <hr />
+
+        <div class="row">
+            <div class="col-md-7">
+                <!-- Theme -->
+                <div class="mb-4">
+                    <label class="form-label fw-bold">Theme</label>
+                    <div>
+                        @foreach (var t in Themes)
+                        {
+                            var theme = t;
+                            <div class="form-check form-check-inline">
+                                <input class="form-check-input" type="radio" name="theme"
+                                       id="@($"theme-{theme}")" value="@theme"
+                                       checked="@(_theme == theme)"
+                                       @onchange="() => _theme = theme" />
+                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
+                            </div>
+                        }
+                    </div>
+                </div>
+
+                <!-- Font Size -->
+                <div class="mb-4">
+                    <label class="form-label fw-bold">Font Size</label>
+                    <div>
+                        @foreach (var fs in FontSizes)
+                        {
+                            var size = fs;
+                            <div class="form-check form-check-inline">
+                                <input class="form-check-input" type="radio" name="fontSize"
+                                       id="@($"fs-{size}")" value="@size"
+                                       checked="@(_fontSize == size)"
+                                       @onchange="() => _fontSize = size" />
+                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
+                            </div>
+                        }
+                    </div>
+                </div>
+
+                <!-- Language -->
+                <div class="mb-4">
+                    <label class="form-label fw-bold">Language</label>
+                    <select class="form-select" @bind="_language">
+                        @foreach (var lang in Languages)
+                        {
+                            <option value="@lang">@lang</option>
+                        }
+                    </select>
+                </div>
+
+                <!-- Compact Mode -->
+                <div class="mb-4">
+                    <div class="form-check form-switch">
+                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
+                        <label class="form-check-label" for="compactMode">Compact Mode</label>
+                    </div>
+                </div>
+
+                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
+            </div>
+
+            <!-- Live Preview -->
+            <div class="col-md-5">
+                <label class="form-label fw-bold">Live Preview</label>
+                <div class="live-preview" style="background:@PreviewBackground; color:@PreviewColor; font-size:@PreviewFontSize; padding: @(_compactMode ? "0.5rem" : "1.25rem");">
+                    <div style="font-weight:600; margin-bottom: @(_compactMode ? "0.25rem" : "0.75rem"); font-size:1.1em;">
+                        Dashboard
+                    </div>
+                    <p style="margin-bottom: @(_compactMode ? "0.25rem" : "0.5rem");">
+                        Welcome back, Jane! Here's your activity summary for today.
+                    </p>
+                    <div style="display:flex; gap: @(_compactMode ? "0.5rem" : "1rem"); flex-wrap:wrap;">
+                        <div class="preview-card" style="background:@(_theme == "Dark" ? "#2d2d2d" : "#f8f9fa"); padding: @(_compactMode ? "0.4rem 0.6rem" : "0.75rem 1rem"); border-radius:6px; flex:1; min-width:80px;">
+                            <div style="font-size:0.8em; opacity:0.7;">Messages</div>
+                            <div style="font-weight:600;">24</div>
+                        </div>
+                        <div class="preview-card" style="background:@(_theme == "Dark" ? "#2d2d2d" : "#f8f9fa"); padding: @(_compactMode ? "0.4rem 0.6rem" : "0.75rem 1rem"); border-radius:6px; flex:1; min-width:80px;">
+                            <div style="font-size:0.8em; opacity:0.7;">Tasks</div>
+                            <div style="font-weight:600;">7</div>
+                        </div>
+                    </div>
+                    <div class="mt-2 small" style="opacity:0.5;">
+                        Theme: @_theme · Font: @_fontSize · Lang: @_language @(_compactMode ? "· Compact" : "")
+                    </div>
+                </div>
+            </div>
+        </div>
+    };
+}
